272	export function useMemoComments(name: string, options?: { enabled?: boolean; pageSize?: number }) {
273	  return useQuery({
274	    queryKey: [...memoKeys.comments(name), options?.pageSize ?? 0],
275	    queryFn: async () => {
276	      const response = await memoServiceClient.listMemoComments(
277	        create(ListMemoCommentsRequestSchema, {
278	          name,
279	          pageSize: options?.pageSize ?? 0,
280	        }),
281	      );
282	      return response;
283	    },
284	    enabled: options?.enabled ?? true,
285	    staleTime: 1000 * 60, // 1 minute
286	  });
